import numpy as np, os
inp=[[0]*10 for _ in range(10)]
for r in range(6,10): inp[r][0]=7
for r in range(7,10):
 for c in (2,3): inp[r][c]=8
for r in range(7,10): inp[r][5]=6
for r in range(8,10):
 for c in (7,8): inp[r][c]=3
def transform(grid):
 H=len(grid); W=len(grid[0]); comps=[]; seen=set()
 for r in range(H):
  for c in range(W):
   col=grid[r][c]
   if col and (r,c) not in seen:
    stack=[(r,c)]; seen.add((r,c)); cells=[]
    while stack:
     y,x=stack.pop(); cells.append((y,x))
     for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
      yy,xx=q
      if 0<=yy<H and 0<=xx<W and grid[yy][xx]==col and q not in seen: seen.add(q); stack.append(q)
    comps.append((min(x for y,x in cells),col,cells))
 comps.sort()
 out=[[0]*W for _ in range(H)]; rr=cc=0
 for _,col,cells in comps:
  r0=min(y for y,x in cells); c0=min(x for y,x in cells)
  h=max(y for y,x in cells)-r0+1; w=max(x for y,x in cells)-c0+1
  for y,x in cells:
   if rr+y-r0<H and cc+x-c0<W: out[rr+y-r0][cc+x-c0]=col
  rr+=h-1; cc+=w-1
 return out
out=transform(inp)
print('\n'.join(' '.join(map(str,row)) for row in out))
